dashboard.definition:
{
    "title": "Lab and Radiology",
    "description": "LIS results with TAT and HIS delivery, RIS orders by modality and DICOM stores in the PACS",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Department",
            "options": {
                "items": [
                    {
                        "label": "All departments",
                        "value": "*"
                    },
                    {
                        "label": "Internal Medicine (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Cardiology (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurology (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Oncology (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "General Surgery (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Trauma Surgery/Orthopedics (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urology (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anesthesia/OR (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensive Care (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Emergency Department (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiology (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynecology/Obstetrics (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Pediatrics (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatry (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "lab_test": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_lis": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:lis:result\" department=\"$dept$\"\n| fields Direction Ward _time c category count critical delivered_to_kis delivery_status flag m n pos priority tat_min test_code u value ward",
                "enableSmartSources": true
            },
            "name": "Lab results"
        },
        "ds_k_results": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=30m count as Results"
            }
        },
        "ds_k_crit": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| eval c=if(critical=\"true\" OR critical=\"1\", 1, 0) | timechart span=30m sum(c) as \"Critical values\""
            }
        },
        "ds_k_tat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where priority=\"Emergency\" | timechart span=30m avg(tat_min) as \"TAT Emergency\""
            }
        },
        "ds_k_undeliv": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| eval u=if(delivered_to_kis=\"false\" OR delivered_to_kis=\"0\", 1, 0) | timechart span=10m sum(u) as \"Not in HIS\""
            }
        },
        "ds_k_flu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where test_code=\"INFLU\" | stats count(eval(value=\"positive\")) as pos count as n | eval \"Influenza positive %\"=if(n>0, round(100 * pos / n, 1), 0) | fields \"Influenza positive %\""
            }
        },
        "ds_cat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=30m count by category"
            }
        },
        "ds_tat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where category!=\"Microbiology\" | timechart span=30m avg(tat_min) by priority"
            }
        },
        "ds_delivery": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=10m count by delivery_status"
            }
        },
        "ds_crit": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en department=\"$dept$\" ((sourcetype=\"sakh:lis:result\" (flag=\"HH\" OR flag=\"LL\")) OR sourcetype=\"sakh:lis:critical\")\n| eventstats min(eval(if(sourcetype=\"sakh:lis:critical\", _time, null()))) as ack_start\n| eval rt=if(sourcetype=\"sakh:lis:result\", _time, null()), acked=if(action=\"acknowledged\", minutes, null()), ack_role=if(action=\"acknowledged\", role, null()), told=if(action=\"communicated\", 1, null()), esc=if(action=\"escalated\", escalation_level, null()), why=if(action=\"escalated\", reason, null())\n| stats min(rt) as rt max(acked) as ack_min first(ack_role) as ack_role max(told) as told max(esc) as escalated first(why) as reason first(test_code) as test_code first(test_name) as test_name first(value) as value first(unit) as unit first(ref_low) as ref_low first(ref_high) as ref_high first(crit_low) as crit_low first(crit_high) as crit_high first(flag) as flag first(ward) as ward first(priority) as priority first(delivery_status) as delivery_status first(patient_id) as patient_id first(ack_start) as ack_start by order_id\n| where isnotnull(rt)\n| eval ack_state=case(isnotnull(ack_min), \"acknowledged\", rt>=ack_start, \"open\", true(), \"unknown\")\n| eval _time=rt | sort - _time | head 300\n| table _time test_code test_name value unit ref_low ref_high crit_low crit_high flag ward priority delivery_status patient_id ack_state ack_min ack_role escalated reason",
                "enableSmartSources": true
            },
            "name": "Critical results with acknowledgement"
        },
        "ds_open": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en department=\"$dept$\" earliest=-4h latest=now ((sourcetype=\"sakh:lis:result\" (flag=\"HH\" OR flag=\"LL\")) OR sourcetype=\"sakh:lis:critical\")\n| eventstats min(eval(if(sourcetype=\"sakh:lis:critical\", _time, null()))) as ack_start\n| eval rt=if(sourcetype=\"sakh:lis:result\", _time, null()), acked=if(action=\"acknowledged\", minutes, null()), ack_role=if(action=\"acknowledged\", role, null()), told=if(action=\"communicated\", 1, null()), esc=if(action=\"escalated\", escalation_level, null()), why=if(action=\"escalated\", reason, null())\n| stats min(rt) as rt max(acked) as ack_min first(ack_role) as ack_role max(told) as told max(esc) as escalated first(why) as reason first(test_code) as test_code first(test_name) as test_name first(value) as value first(unit) as unit first(ref_low) as ref_low first(ref_high) as ref_high first(crit_low) as crit_low first(crit_high) as crit_high first(flag) as flag first(ward) as ward first(priority) as priority first(delivery_status) as delivery_status first(patient_id) as patient_id first(ack_start) as ack_start by order_id\n| where isnotnull(rt)\n| eval ack_state=case(isnotnull(ack_min), \"acknowledged\", rt>=ack_start, \"open\", true(), \"unknown\")\n| where ack_state=\"open\" | eval age=round((now() - rt) / 60, 0)",
                "enableSmartSources": true
            },
            "name": "Open critical results"
        },
        "ds_k_open": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_open",
                "query": "| stats count as \"Not acknowledged\""
            }
        },
        "ds_k_overdue": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_open",
                "query": "| where age>30 | stats count as \"Over 30 min\""
            }
        },
        "ds_open_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_open",
                "query": "| sort - age\n| eval Status=case(escalated>=2, \"2nd escalation: attending on duty\", escalated=1, \"escalated to attending physician\", told=1, \"communicated by phone\", true(), \"not yet communicated\"), Value=value.\" \".unit, Direction=if(flag=\"HH\", \"too high\", \"too low\")\n| table ward age test_name Value Status reason delivery_status\n| rename ward as Ward age as \"Open for (min)\" test_name as Test reason as Reason delivery_status as HIS\n| appendpipe [| stats count | where count=0 | eval Ward=\"All critical values are acknowledged\" | fields - count]"
            }
        },
        "ds_ack": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:lis:critical\" department=\"$dept$\"\n| fields Duration _time action count h minutes ok",
                "enableSmartSources": true
            },
            "name": "Critical value notification"
        },
        "ds_k_ack_med": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ack",
                "query": "| where action=\"acknowledged\" | timechart span=1h median(minutes) as \"Median\""
            }
        },
        "ds_k_ack_30": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ack",
                "query": "| where action=\"acknowledged\" | eval ok=if(minutes<=30, 100, 0) | timechart span=1h avg(ok) as \"Within 30 min\""
            }
        },
        "ds_ack_buckets": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ack",
                "query": "| where action=\"acknowledged\"\n| eval Duration=case(minutes<=10, \"up to 10 min\", minutes<=30, \"10 to 30 min\", true(), \"over 30 min (escalated)\")\n| timechart span=1h count by Duration"
            }
        },
        "ds_crit_ward": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| search (flag=\"HH\" OR flag=\"LL\") test_code=\"$lab_test$\"\n| eval Direction=if(flag=\"HH\", \"too high\", \"too low\")\n| chart count over ward by Direction | rename ward as Ward\n| appendpipe [| stats count | where count=0 | eval Ward=\"No critical values in the time range\" | fields - count]"
            }
        },
        "ds_ris": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:ris:order\" department=\"$dept$\"\n| fields Days Time _time count device_id exam modality order_id original_device priority reason status wait_days",
                "enableSmartSources": true
            },
            "name": "RIS orders"
        },
        "ds_modality": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| chart count over modality by status"
            }
        },
        "ds_wait": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| where priority=\"Routine\" | stats avg(wait_days) as \"Wait (days)\" by modality | eval \"Wait (days)\"=round('Wait (days)', 1)"
            }
        },
        "ds_moved": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| where status=\"rescheduled\"\n| eval Time=strftime(_time, \"%H:%M\") | table Time order_id exam original_device device_id reason wait_days\n| rename order_id as Order exam as Exam original_device as \"Planned on\" device_id as \"Moved to\" reason as Reason wait_days as \"Wait (days)\"\n| appendpipe [| stats count | where count=0 | eval Time=\"No rescheduled exams in the time range\" | fields - count]"
            }
        },
        "ds_pacs": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:pacs:dicom\" | timechart span=30m sum(size_mb) as MB by modality",
                "enableSmartSources": true
            },
            "name": "PACS data volume"
        },
        "ds_pacs_fail": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:pacs:dicom\" status!=\"Success\" | stats count as Error by device_id status | rename device_id as Modality status as Fault | appendpipe [| stats count | where count=0 | eval Modality=\"No store failures in the time range\" | fields - count]",
                "enableSmartSources": true
            }
        },
        "ds_device": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| stats count by device_id | sort - count | head 12"
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_care.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_beds",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_diag": {
            "type": "splunk.image",
