        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_results"
            },
            "options": {
                "majorColor": "#b8457c",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_crit"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 5,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 5,
                        "to": 10,
                        "value": "#c98a00"
                    },
                    {
                        "from": 10,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_tat"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 45,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 45,
                        "to": 60,
                        "value": "#c98a00"
                    },
                    {
                        "from": 60,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_undeliv"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 1,
                        "to": 10,
                        "value": "#c98a00"
                    },
                    {
                        "from": 10,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_flu"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#0b7fab",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 20,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 20,
                        "to": 40,
                        "value": "#c98a00"
                    },
                    {
                        "from": 40,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "splunk.column",
            "dataSources": {
                "primary": "ds_cat"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
                ],
                "stackMode": "stacked"
            }
        },
        "viz_07": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_tat"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
                ],
                "lineWidth": 2
            }
        },
        "viz_08": {
            "type": "splunk.column",
            "dataSources": {
                "primary": "ds_delivery"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#c8253f",
                    "#1e8a5a"
                ],
                "stackMode": "stacked"
            }
        },
        "viz_09": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_open"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 3,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 3,
                        "to": 6,
                        "value": "#c98a00"
                    },
                    {
                        "from": 6,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_10": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_overdue"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 1,
                        "to": 2,
                        "value": "#c98a00"
                    },
                    {
                        "from": 2,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_11": {
